package pt.realmmarriage.domain;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import pt.realmmarriage.domain.MarriageLedger.*;
class MarriageLedgerTest {
    private static final UUID A=new UUID(1,1),B=new UUID(1,2),PRIEST=new UUID(1,3),GUEST=new UUID(1,4),OTHER=new UUID(1,5);
    private static final long NOW=1792497600000L;
    private MarriageLedger ledger(){MarriageLedger d=new MarriageLedger();for(UUID p:List.of(A,B,PRIEST,GUEST,OTHER))d.citizen(p,"RP "+p.getLeastSignificantBits());return d;}
    private Union engaged(MarriageLedger d){Union u=d.propose(A,B,NOW);d.answer(u,B,true,NOW+1);d.configure(u,A,PRIEST,List.of(GUEST),Mode.SEPARATE,5000,0,NOW+2);d.agree(u,A,NOW+3);d.agree(u,B,NOW+4);d.invitation(u,PRIEST,true,NOW+5);d.invitation(u,GUEST,true,NOW+6);return u;}
    private Union vows(MarriageLedger d){Union u=engaged(d);d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10);d.next(u,PRIEST,NOW+11);d.next(u,PRIEST,NOW+12);d.tick(NOW+10012);return u;}
    private Union committing(MarriageLedger d){Union u=vows(d);d.ask(u,PRIEST,NOW+10013);d.vow(u,A,NOW+10014);d.ask(u,PRIEST,NOW+10015);d.vow(u,B,NOW+10016);d.witness(u,GUEST,NOW+10017);d.seal(u,PRIEST,NOW+10018);return u;}
    private Union married(MarriageLedger d,long balance,Mode mode){Union u=committing(d);u.mode=mode;for(UUID p:List.of(A,B)){Operation o=d.op(UUID.randomUUID(),p,u,Kind.FUND,p.equals(A)?balance:0,0,"",NOW+10019);d.settled(o,NOW+10020);}d.finish(u,NOW+10021);return u;}
    @Test void cannotProposeToSelf(){var d=ledger();assertThrows(IllegalStateException.class,()->d.propose(A,A,NOW));}
    @Test void proposalRequiresRecipientsConsent(){var d=ledger();var u=d.propose(A,B,NOW);assertEquals(Phase.PROPOSED,u.phase);assertThrows(IllegalStateException.class,()->d.answer(u,A,true,NOW));assertThrows(IllegalStateException.class,()->d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW));}
    @Test void oneActiveRelationshipPerUuid(){var d=ledger();d.propose(A,B,NOW);assertThrows(IllegalStateException.class,()->d.propose(OTHER,B,NOW));}
    @Test void decliningReleasesBothPeople(){var d=ledger();var u=d.propose(A,B,NOW);d.answer(u,B,false,NOW+1);assertNull(d.current(A));assertNull(d.current(B));assertNotNull(d.propose(OTHER,B,NOW+2));}
    @Test void proposalsExpireWithoutReconnectionReset(){var d=ledger();var u=d.propose(A,B,NOW);d=MarriageLedger.fromJson(MarriageLedger.JSON.toJson(d));d.tick(u.expiresAt);assertNull(d.current(A));}
    @Test void anExpiredProposalCannotBeAccepted(){var d=ledger();var u=d.propose(A,B,NOW);assertThrows(IllegalStateException.class,()->d.answer(u,B,true,u.expiresAt));}
    @Test void arbitraryPlayerCannotBeTheCelebrant(){var d=ledger();var u=engaged(d);assertThrows(IllegalStateException.class,()->d.start(u,OTHER,"minecraft:overworld",0,64,0,NOW+10));}
    @Test void celebrantMustAcceptTheirInvitation(){var d=ledger();var u=engaged(d);d.invitation(u,PRIEST,false,NOW+7);assertThrows(IllegalStateException.class,()->d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10));}
    @Test void onlyTwoAgreedInvitationsGrantTheTemporaryRole(){var d=ledger();var u=engaged(d);long revision=d.revision;d.agree(u,A,NOW+8);assertEquals(revision,d.revision,"A repeated approval must not replay invitations or add audit entries");d.configure(u,B,OTHER,List.of(),Mode.SHARED,5000,0,NOW+10);assertFalse(u.priestAccepted);assertTrue(u.plan.isEmpty());assertThrows(IllegalStateException.class,()->d.invitation(u,OTHER,true,NOW+11));}
    @Test void aSpouseCannotBeTheirOwnCelebrantOrWitness(){var d=ledger();var u=engaged(d);assertThrows(IllegalStateException.class,()->d.configure(u,A,A,List.of(),Mode.SEPARATE,5000,0,NOW));assertThrows(IllegalStateException.class,()->d.configure(u,A,PRIEST,List.of(A),Mode.SEPARATE,5000,0,NOW));}
    @Test void duplicateOrExcessWitnessesAreRejected(){var d=ledger();var u=engaged(d);assertThrows(IllegalStateException.class,()->d.configure(u,A,PRIEST,List.of(GUEST,GUEST),Mode.SEPARATE,5000,0,NOW));assertThrows(IllegalStateException.class,()->d.configure(u,A,PRIEST,List.of(GUEST,OTHER,B),Mode.SEPARATE,5000,0,NOW));}
    @Test void witnessesMustAcceptBeforeTheCeremony(){var d=ledger();var u=engaged(d);d.invitation(u,GUEST,false,NOW);assertThrows(IllegalStateException.class,()->d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW));}
    @Test void theTenSecondObjectionWindowIsServerControlled(){var d=ledger();var u=engaged(d);d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10);d.next(u,PRIEST,NOW+11);d.next(u,PRIEST,NOW+12);d.tick(NOW+10011);assertEquals(Phase.OBJECTIONS,u.phase);d.tick(NOW+10012);assertEquals(Phase.VOWS,u.phase);}
    @Test void anObjectionSuspendsButDoesNotCancel(){var d=ledger();var u=engaged(d);d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10);d.next(u,PRIEST,NOW+11);d.next(u,PRIEST,NOW+12);d.objection(u,GUEST,NOW+100);assertEquals(Phase.SUSPENDED,u.phase);assertNotNull(d.current(A));}
    @Test void spousesCannotObjectAndOnlyOneObjectionIsAccepted(){var d=ledger();var u=engaged(d);d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10);d.next(u,PRIEST,NOW+11);d.next(u,PRIEST,NOW+12);assertThrows(IllegalStateException.class,()->d.objection(u,A,NOW+50));d.objection(u,GUEST,NOW+100);assertThrows(IllegalStateException.class,()->d.objection(u,OTHER,NOW+101));}
    @Test void anObjectionAtTheDeadlineIsRejected(){var d=ledger();var u=engaged(d);d.start(u,PRIEST,"minecraft:overworld",0,64,0,NOW+10);d.next(u,PRIEST,NOW+11);d.next(u,PRIEST,NOW+12);assertThrows(IllegalStateException.class,()->d.objection(u,GUEST,u.objectionUntil));}
    @Test void onlyTheObjectorMayGiveTheirReason(){var d=ledger();var u=vows(d);u.phase=Phase.OBJECTIONS;u.objectionUntil=NOW+20000;d.objection(u,GUEST,NOW+11000);assertThrows(IllegalStateException.class,()->d.reason(u,OTHER,"Forged",NOW+11001));d.reason(u,GUEST,"Let us hear the couple.",NOW+11002);assertEquals("Let us hear the couple.",u.reason);}
    @Test void reasonsAreBoundedAndCannotCarryControlCharacters(){var d=ledger();var u=vows(d);u.phase=Phase.SUSPENDED;u.objector=GUEST;assertThrows(IllegalStateException.class,()->d.reason(u,GUEST,"x".repeat(257),NOW));assertThrows(IllegalStateException.class,()->d.reason(u,GUEST,"bad\ntext",NOW));}
    @Test void bothSpousesMustAgreeToResume(){var d=ledger();var u=vows(d);d.suspend(u,"absence",NOW+11000);d.continueVote(u,A,NOW+11001);assertThrows(IllegalStateException.class,()->d.resume(u,PRIEST,NOW+11002));d.continueVote(u,B,NOW+11003);d.resume(u,PRIEST,NOW+11004);assertEquals(Phase.VOWS,u.phase);}
    @Test void suspensionInvalidatesPreviousVows(){var d=ledger();var u=vows(d);d.ask(u,PRIEST,NOW+11000);d.vow(u,A,NOW+11001);d.suspend(u,"disconnect",NOW+11002);assertTrue(u.vows.isEmpty());assertEquals(0,u.vowTurn);}
    @Test void vowsAreAskedIndividuallyInOrder(){var d=ledger();var u=vows(d);assertThrows(IllegalStateException.class,()->d.vow(u,A,NOW));d.ask(u,PRIEST,NOW+11000);assertThrows(IllegalStateException.class,()->d.vow(u,B,NOW));assertThrows(IllegalStateException.class,()->d.ask(u,PRIEST,NOW));d.vow(u,A,NOW+11001);d.ask(u,PRIEST,NOW+11002);d.vow(u,B,NOW+11003);assertEquals(Set.of(A,B),u.vows);}
    @Test void celebrantCannotSealWithoutBothVowsAndWitnesses(){var d=ledger();var u=vows(d);assertThrows(IllegalStateException.class,()->d.seal(u,PRIEST,NOW));d.ask(u,PRIEST,NOW+11000);d.vow(u,A,NOW+11001);d.ask(u,PRIEST,NOW+11002);d.vow(u,B,NOW+11003);assertThrows(IllegalStateException.class,()->d.seal(u,PRIEST,NOW));d.witness(u,GUEST,NOW+11004);d.seal(u,PRIEST,NOW+11005);assertEquals(Phase.COMMITTING,u.phase);}
    @Test void officialMarriageWaitsForFundedReceiptsAndPublicFee(){var d=ledger();var u=committing(d);assertThrows(IllegalStateException.class,()->d.finish(u,NOW));u.fundedA=true;u.fundedB=true;u.fee=100;u.feeEscrow=100;assertThrows(IllegalStateException.class,()->d.finish(u,NOW));u.feeTransferred=true;u.feeEscrow=0;d.finish(u,NOW+20000);assertEquals(Phase.MARRIED,u.phase);assertFalse(u.priestAccepted);}
    @Test void cancellingBeforeFinancialCommitDoesNotHoldAnyoneInTheRelationship(){var d=ledger();var u=engaged(d);d.cancel(u,A,NOW+10);assertNull(d.current(A));assertNull(d.current(B));assertFalse(u.priestAccepted);}
    @Test void cancellingFundedPendingCeremonyReturnsEachOriginalContribution(){var d=ledger();var u=committing(d);u.mode=Mode.JOINT;u.fee=1000;Operation o=d.op(UUID.randomUUID(),A,u,Kind.FUND,50000,500,"",NOW+20000);d.settled(o,NOW+20001);d.cancel(u,B,NOW+20002);d.abortFinancial(u,NOW+20003);assertEquals(50000,d.citizen(A).credit());assertEquals(0,d.citizen(B).credit());assertNull(d.current(B));d.validate();}
    @Test void aLateFundingReceiptAfterCancellationStillRefundsItsOriginalOwner(){var d=ledger();var u=committing(d);u.mode=Mode.JOINT;u.fee=1000;Operation o=d.op(UUID.randomUUID(),A,u,Kind.FUND,50000,500,"",NOW+20000);d.cancel(u,B,NOW+20001);d.abortFinancial(u,NOW+20002);d.settled(o,NOW+20003);assertEquals(50000,d.citizen(A).credit());d.validate();}
    @Test void anySpouseCanDivorceWithoutTheOtherPlayerOnlineOrAgreeing(){var d=ledger();var u=married(d,80001,Mode.JOINT);d.divorce(u,B,NOW+30000);assertEquals(40000,d.citizen(A).credit());assertEquals(40001,d.citizen(B).credit());assertEquals(0,u.balance);assertNull(d.current(A));assertEquals("DIVORCED",d.status(B));d.validate();}
    @Test void separateMoneyHasNoSharedFundsToDivide(){var d=ledger();var u=married(d,0,Mode.SEPARATE);d.divorce(u,A,NOW+30000);assertEquals(0,d.citizen(A).credit()+d.citizen(B).credit());}
    @Test void negotiatedDivisionDoesNotLoseIndivisibleCents(){var d=ledger();var u=married(d,10001,Mode.SHARED);u.shareA=3300;d.divorce(u,A,NOW+30000);assertEquals(3300,d.citizen(A).credit());assertEquals(6701,d.citizen(B).credit());}
    @Test void divorcedPeopleCanRemarryWhileTheirOwnCreditsRemainReserved(){var d=ledger();var u=married(d,10000,Mode.JOINT);d.divorce(u,A,NOW+30000);d.propose(A,OTHER,NOW+30001);assertEquals(5000,d.citizen(A).credit());}
    @Test void withdrawalsAreLockedAfterDivorce(){var d=ledger();var u=married(d,10000,Mode.SHARED);d.divorce(u,A,NOW+30000);assertThrows(IllegalStateException.class,()->d.withdrawReserve(u,A,1));}
    @Test void anotherPlayerCannotWithdrawOrDivorce(){var d=ledger();var u=married(d,10000,Mode.SHARED);assertThrows(IllegalStateException.class,()->d.withdrawReserve(u,OTHER,1));assertThrows(IllegalStateException.class,()->d.divorce(u,OTHER,NOW+30000));}
    @Test void paymentReceiptsAreBoundToTheFullPayload(){var d=ledger();var u=married(d,10000,Mode.SHARED);UUID id=UUID.randomUUID();var o=d.reservePayment(id,A,u.id,"market",1000,NOW+30000);assertSame(o,d.reservePayment(id,A,u.id,"market",1000,NOW+30001));assertEquals(9000,u.balance);assertThrows(IllegalStateException.class,()->d.reservePayment(id,A,u.id,"market",1001,NOW+30002));assertThrows(IllegalStateException.class,()->d.payment(id,"other",true,NOW));}
    @Test void committedPaymentsCannotBeRefundedOrCommittedTwice(){var d=ledger();var u=married(d,10000,Mode.SHARED);UUID id=UUID.randomUUID();d.reservePayment(id,A,u.id,"market",1000,NOW+30000);d.payment(id,"market",true,NOW+30001);d.payment(id,"market",true,NOW+30002);assertEquals(9000,u.balance);assertThrows(IllegalStateException.class,()->d.payment(id,"market",false,NOW));}
    @Test void cancelledPurchasesReturnOnlyTheirOriginalFundedEscrow(){var d=ledger();var u=married(d,10000,Mode.SHARED);UUID id=UUID.randomUUID();d.reservePayment(id,A,u.id,"market",1000,NOW+30000);d.payment(id,"market",false,NOW+30001);d.payment(id,"market",false,NOW+30002);assertEquals(10000,u.balance);}
    @Test void purchaseRefundAfterDivorceRespectsTheOriginalDivision(){var d=ledger();var u=married(d,10001,Mode.SHARED);UUID id=UUID.randomUUID();d.reservePayment(id,A,u.id,"market",1001,NOW+30000);d.divorce(u,A,NOW+30001);d.payment(id,"market",false,NOW+30002);assertEquals(5000,d.citizen(A).credit());assertEquals(5001,d.citizen(B).credit());d.validate();}
    @Test void anInterruptedDepositDoesNotBecomeLostAfterDivorce(){var d=ledger();var u=married(d,10000,Mode.JOINT);Operation o=d.op(UUID.randomUUID(),A,u,Kind.DEPOSIT,1001,0,"",NOW+30000);d.divorce(u,B,NOW+30001);d.settled(o,NOW+30002);assertEquals(5500,d.citizen(A).credit());assertEquals(5501,d.citizen(B).credit());assertEquals(0,u.balance);d.validate();}
    @Test void repeatedFinancialSettlementDoesNotIssueMoneyTwice(){var d=ledger();var u=married(d,10000,Mode.SHARED);Operation o=d.op(UUID.randomUUID(),A,u,Kind.DEPOSIT,1000,0,"",NOW+30000);d.settled(o,NOW+30001);assertThrows(IllegalStateException.class,()->d.settled(o,NOW+30002));assertEquals(11000,u.balance);}
    @Test void registryReloadKeepsRelationshipsCreditsAndReceipts(){var d=ledger();var u=married(d,80001,Mode.JOINT);d.divorce(u,A,NOW+30000);var next=MarriageLedger.fromJson(MarriageLedger.JSON.toJson(d));assertEquals(40001,next.citizen(B).credit());assertEquals(d.operations.keySet(),next.operations.keySet());assertEquals(Phase.DIVORCED,next.union(u.id).phase);}
    @Test void negativeAndExcessivePoliciesAreRejected(){Settings s=new Settings();s.objectionSeconds=-1;assertThrows(IllegalStateException.class,s::validate);s=new Settings();s.fee=50001;assertThrows(IllegalStateException.class,s::validate);s=new Settings();s.witnessLimit=3;assertThrows(IllegalStateException.class,s::validate);}
    @Test void corruptedSpouseReferencesCannotRecreateAnEmptyRegistry(){var d=ledger();var u=engaged(d);d.citizen(A).current=null;assertThrows(IllegalStateException.class,d::validate);}
    @Test void movingTheClockBackCannotExtendAProposal(){var d=ledger();var u=d.propose(A,B,NOW);d.now(u.expiresAt);assertThrows(IllegalStateException.class,()->d.answer(u,B,true,NOW));}
    @Test void ceremoniesHaveABoundedLifetime(){var d=ledger();var u=vows(d);d.tick(u.expiresAt);assertEquals(Phase.CANCELLED,u.phase);}
    @Test void pendingFeeDoesNotPreventEndingTheRelationship(){var d=ledger();var u=committing(d);u.fee=1000;for(UUID p:List.of(A,B)){var o=d.op(UUID.randomUUID(),p,u,Kind.FUND,5000,500,"",NOW+20000);d.settled(o,NOW+20001);}u.feeAttempted=true;d.cancel(u,A,NOW+20002);d.cancelCommitted(u,A,NOW+20003);assertNull(d.current(A));assertNull(d.current(B));assertEquals(9000,d.citizen(A).credit()+d.citizen(B).credit());assertEquals(1000,u.feeEscrow);d.validate();}
    @Test void smallRefundsAfterDivorceCannotBiasTheAgreedPercentage(){var d=ledger();var u=married(d,100,Mode.SHARED);List<UUID> receipts=new ArrayList<>();for(int i=0;i<99;i++){UUID id=UUID.randomUUID();receipts.add(id);d.reservePayment(id,A,u.id,"market",1,NOW+30000);}d.divorce(u,B,NOW+30001);for(UUID id:receipts)d.payment(id,"market",false,NOW+30002);assertEquals(50,d.citizen(A).credit());assertEquals(50,d.citizen(B).credit());d.validate();}
}
